email.content:
Hi {$DATA.first_name|capitalize},

We're pleased to let you know that order number {$DATA.cart_order_id} is now complete. If you ordered physical goods, they should be with you soon.
{if !empty($DATA.ship_tracking)}
Track your order:
{$DATA.ship_tracking}
{/if}

Thank you for your order, {$DATA.first_name|capitalize}.

We've received your order {$DATA.cart_order_id}, placed on {$DATA.order_date}. Please keep this email for your records. You can view your order status online at any time.

{$DATA.link}

----------------------------------------------------------------------
Billing address:
{$BILLING.first_name|capitalize} {$BILLING.last_name|capitalize}
{if !empty($BILLING.company_name)}{$BILLING.company_name}
{/if}{$BILLING.line1|capitalize}
{if !empty($BILLING.line2)}{$BILLING.line2|capitalize}
{/if}{$BILLING.town|upper}
{if !empty($BILLING.state)}{$BILLING.state|upper}
{/if}{$BILLING.postcode}
{$BILLING.country}{if !empty($BILLING.w3w)}
///{$BILLING.w3w}{/if}
{$BILLING.phone}

Email:
{$BILLING.email}

Shipping address:
{$SHIPPING.first_name|capitalize} {$SHIPPING.last_name|capitalize}
{if !empty($SHIPPING.company_name)}{$SHIPPING.company_name}
{/if}{$SHIPPING.line1|capitalize}
{if !empty($SHIPPING.line2)}{$SHIPPING.line2|capitalize}
{/if}{$SHIPPING.town|upper}
{if !empty($SHIPPING.state)}{$SHIPPING.state|upper}
{/if}{$SHIPPING.postcode}
{$SHIPPING.country}{if !empty($SHIPPING.w3w)}
///{$SHIPPING.w3w}{/if}

----------------------------------------------------------------------
Items in Your Order

{foreach from=$PRODUCTS item=product}
-----------------------------------
{$product.name}
{$product.product_options}

Part Number: {$product.product_code}
Unit Price: {$product.price}
Qty: {$product.quantity}

{/foreach}
-----------------------------------
Subtotal: {$DATA.subtotal}
Discount: {$DATA.discount}
{if !empty($DATA.ship_method)}{$DATA.ship_method}:{if !empty($DATA.ship_product)} ({$DATA.ship_product}){/if}{else}Shipping:{/if} {$DATA.shipping}
{foreach from=$TAXES item=tax}{$tax.tax_name} ({$tax.tax_percent}%): {$tax.tax_amount}
{/foreach}{if $DATA.show_credit}
Credit: ({$DATA.credit_used})
{/if}--------------------------
Order Total: {$DATA.total}
==========================
{if !empty($DATA.note_to_customer)}
"{$DATA.note_to_customer}"{/if}

{$DATA.first_name|capitalize} {$DATA.last_name|capitalize} {if !empty($BILLING.company_name)}({$BILLING.company_name}){/if} just placed order number {$DATA.cart_order_id} on {$DATA.order_date}.

You can manage this order using the link below.

{$DATA.link}

----------------------------------------------------------------------
Billing address:
{$BILLING.first_name|capitalize} {$BILLING.last_name|capitalize}
{if !empty($BILLING.company_name)}{$BILLING.company_name}
